<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Mail;
class CampaignService {
 public function audience($segment){$query=DB::table('users as u')->leftJoin('orders as o','o.user_id','=','u.id')->select('u.id as user_id','u.name','u.email',DB::raw("COUNT(CASE WHEN o.status <> 'cancelled' THEN 1 END) order_count"),DB::raw("COALESCE(SUM(CASE WHEN o.status <> 'cancelled' THEN o.total ELSE 0 END),0) total_spend"),DB::raw('MAX(o.created_at) last_order'))->groupBy('u.id','u.name','u.email');if($segment->minimum_orders)$query->havingRaw('order_count >= ?',[$segment->minimum_orders]);if($segment->minimum_spend)$query->havingRaw('total_spend >= ?',[$segment->minimum_spend]);if($segment->registered_within_days)$query->where('u.created_at','>=',now()->subDays($segment->registered_within_days));if($segment->inactive_for_days)$query->havingRaw('(last_order IS NULL OR last_order <= ?)',[now()->subDays($segment->inactive_for_days)]);return $query->get();}
 public function prepare($campaignId){$campaign=DB::table('marketing_campaigns')->where('id',$campaignId)->first();$segment=DB::table('customer_segments')->where('id',$campaign->customer_segment_id)->first();$audience=$this->audience($segment);DB::table('campaign_recipients')->where('campaign_id',$campaignId)->delete();foreach($audience as $customer)DB::table('campaign_recipients')->insert(['campaign_id'=>$campaignId,'user_id'=>$customer->user_id,'customer_name'=>$customer->name,'email'=>strtolower($customer->email),'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);DB::table('marketing_campaigns')->where('id',$campaignId)->update(['recipient_count'=>$audience->count(),'status'=>'ready','updated_at'=>now()]);return $audience->count();}
 public function send($campaignId){$campaign=DB::table('marketing_campaigns')->where('id',$campaignId)->first();$coupon=$campaign->coupon_id?DB::table('coupons')->where('id',$campaign->coupon_id)->first():null;$body=$campaign->message.($coupon?"\n\nCoupon code: ".$coupon->code:'');$recipients=DB::table('campaign_recipients')->where('campaign_id',$campaignId)->where('status','pending')->get();$delivered=0;$failed=0;foreach($recipients as $recipient){$status='not_configured';$error=null;if(config('mail.username')){try{Mail::raw($body,function($mail)use($recipient,$campaign){$mail->to($recipient->email)->subject($campaign->subject);});$status='sent';$delivered++;}catch(\Throwable $e){$status='failed';$error=substr($e->getMessage(),0,1000);$failed++;}}if($recipient->user_id)DB::table('store_notifications')->insert(['recipient_type'=>'customer','user_id'=>$recipient->user_id,'email'=>$recipient->email,'title'=>$campaign->subject,'message'=>$body,'action_url'=>url('/'),'email_status'=>$status,'email_error'=>$error,'created_at'=>now(),'updated_at'=>now()]);DB::table('campaign_recipients')->where('id',$recipient->id)->update(['status'=>$status,'error'=>$error,'sent_at'=>now(),'updated_at'=>now()]);}DB::table('marketing_campaigns')->where('id',$campaignId)->update(['status'=>'sent','sent_at'=>now(),'delivered_count'=>$delivered,'failed_count'=>$failed,'updated_at'=>now()]);return $recipients->count();}
}
